  typography: typography,
  // Типографика
  shape: shape,
  // Скругления

  components: {
    // Объединяем все темы компонентов с помощью spread оператора (...)
    ...lightCardTheme,
    ...lightButtonTheme,
    ...lightAppBarTheme,
    ...lightTypographyTheme,
    ...lightBadgeTheme,
