            content: '""',
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(255, 255, 255, 0.85)',
            // Полупрозрачная белая накладка для светлой темы
            zIndex: -1,
            pointerEvents: 'none'
          }
        },
        // Стили для корневого элемента
        'html, #root': {
          minHeight: '100vh',
          position: 'relative',
          zIndex: 1
        }
      }
